    10	public class PriceCalculator {
    11	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
    12	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
    13	
    14	    public static BigDecimal calculateNightPrice(BigDecimal baseRate, LocalDate date) {
    15	        if (isHighSeason(date)) {
    16	            return baseRate.multiply(HIGH_SEASON_MULTIPLIER)
    17	                .setScale(2, RoundingMode.HALF_EVEN);
    18	        }
    19	        return baseRate;
    20	    }
    21	
    22	    public static BigDecimal calculateSubtotal(BigDecimal baseRate, LocalDate checkIn, LocalDate checkOut) {
    23	        BigDecimal subtotal = BigDecimal.ZERO;
    24	        LocalDate current = checkIn;
    25	
    26	        while (current.isBefore(checkOut)) {
    27	            BigDecimal nightPrice = calculateNightPrice(baseRate, current);
    28	            subtotal = subtotal.add(nightPrice);
    29	            current = current.plusDays(1);
    30	        }
    31	
    32	        return subtotal.setScale(2, RoundingMode.HALF_EVEN);
    33	    }
    34	
    35	    public static BigDecimal calculateDiscount(BigDecimal subtotal, RatePlan ratePlan) {
    36	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
    37	            return subtotal.multiply(NON_REFUNDABLE_DISCOUNT)
    38	                .setScale(2, RoundingMode.HALF_EVEN);
    39	        }
    40	        return BigDecimal.ZERO;
    41	    }
