    27	    public Reservation createReservation(Reservation reservation) {
    28	        Room room = roomService.getRoomByNumber(reservation.getRoomNumber());
    29	        if (room == null) {
    30	            throw new RoomNotFoundException();
    31	        }
    32	
    33	        if (reservation.getGuests() > room.getCapacity()) {
    34	            throw new CapacityExceededException();
    35	        }
    36	
    37	        try {
    38	            if (reservationRepository.hasConflict(
    39	                reservation.getRoomNumber(),
    40	                reservation.getCheckIn(),
    41	                reservation.getCheckOut(),
    42	                null
    43	            )) {
    44	                throw new RoomUnavailableException();
    45	            }
    46	        } catch (SQLException e) {
    47	            throw new RuntimeException("Failed to check room availability", e);
    48	        }
    49	
    50	        int nights = (int) ChronoUnit.DAYS.between(reservation.getCheckIn(), reservation.getCheckOut());
    51	        reservation.setNights(nights);
    52	
    53	        BigDecimal subtotal = PriceCalculator.calculateSubtotal(
    54	            room.getNightlyRate(),
    55	            reservation.getCheckIn(),
    56	            reservation.getCheckOut()
    57	        );
    58	        reservation.setSubtotal(subtotal);
    59	
    60	        BigDecimal discount = PriceCalculator.calculateDiscount(subtotal, reservation.getRatePlan());
    61	        reservation.setDiscount(discount);
    62	
    63	        BigDecimal total = PriceCalculator.calculateTotal(subtotal, discount);
    64	        reservation.setTotal(total);
    65	
    66	        try {
    67	            return reservationRepository.save(reservation);
    68	        } catch (SQLException e) {
    69	            throw new RuntimeException("Failed to save reservation", e);
    70	        }
    71	    }
