    21	
    22	    public void createReservation(Context ctx) {
    23	        try {
    24	            CreateReservationRequest req = ctx.bodyAsClass(CreateReservationRequest.class);
    25	
    26	            if (req.roomNumber() == null || req.guestName() == null || req.guestEmail() == null ||
    27	                req.guestCpf() == null || req.checkIn() == null || req.checkOut() == null ||
    28	                req.guests() == null || req.ratePlan() == null) {
    29	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Missing required fields"));
    30	                return;
    31	            }
    32	
    33	            if (req.guests() < 1) {
    34	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "At least one guest is required"));
    35	                return;
    36	            }
    37	
    38	            LocalDate checkIn = LocalDate.parse(req.checkIn());
    39	            LocalDate checkOut = LocalDate.parse(req.checkOut());
    40	
    41	            if (!checkOut.isAfter(checkIn)) {
    42	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Check-out must be after check-in"));
    43	                return;
    44	            }
    45	
    46	            Reservation reservation = new Reservation();
    47	            reservation.setRoomNumber(req.roomNumber());
    48	            reservation.setGuestName(req.guestName());
    49	            reservation.setGuestEmail(req.guestEmail());
    50	            reservation.setGuestCpf(req.guestCpf());
    51	            reservation.setCheckIn(checkIn);
    52	            reservation.setCheckOut(checkOut);
    53	            reservation.setGuests(req.guests());
    54	            reservation.setRatePlan(RatePlan.valueOf(req.ratePlan()));
    55	
    56	            Reservation created = reservationService.createReservation(reservation);
    57	            ctx.status(201).json(ReservationResponse.from(created));
    58	
    59	        } catch (IllegalArgumentException e) {
    60	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid request data"));
    61	        } catch (ReservationService.RoomNotFoundException e) {
    62	            ctx.status(404).json(new ErrorResponse("ROOM_NOT_FOUND", "Room not found"));
    63	        } catch (ReservationService.RoomUnavailableException e) {
    64	            ctx.status(409).json(new ErrorResponse("ROOM_UNAVAILABLE", "Room is not available for the selected dates"));
    65	        } catch (ReservationService.CapacityExceededException e) {
    66	            ctx.status(422).json(new ErrorResponse("CAPACITY_EXCEEDED", "Number of guests exceeds room capacity"));
    67	        }
    68	    }
