     3	import java.util.ArrayList;
     4	import java.util.HashMap;
     5	import java.util.List;
     6	import java.util.Map;
     7	
     8	public class EventBus {
     9	    private final Map<Class<? extends DomainEvent>, List<EventHandler<? extends DomainEvent>>> handlers = new HashMap<>();
    10	
    11	    public <T extends DomainEvent> void subscribe(Class<T> eventType, EventHandler<T> handler) {
    12	        handlers.computeIfAbsent(eventType, k -> new ArrayList<>()).add(handler);
    13	    }
    14	
    15	    @SuppressWarnings("unchecked")
    16	    public <T extends DomainEvent> void publish(T event) {
    17	        List<EventHandler<? extends DomainEvent>> eventHandlers = handlers.get(event.getClass());
    18	        if (eventHandlers != null) {
    19	            for (EventHandler<? extends DomainEvent> handler : eventHandlers) {
    20	                ((EventHandler<T>) handler).handle(event);
    21	            }
    22	        }
    23	    }
    24	}
