    11	        StringBuilder sb = new StringBuilder();
    12	        sb.append(String.format("Comprovante de reserva nº %d%n", reservation.getId()));
    13	        sb.append(String.format("Hóspede: %s (CPF %s)%n",
    14	            reservation.getGuestName(),
    15	            CpfFormatter.format(reservation.getGuestCpf())));
    16	
    17	        RoomType roomType = RoomRepository.getRoomType(reservation.getRoomNumber());
    18	        sb.append(String.format("Quarto: %s (%s)%n",
    19	            reservation.getRoomNumber(),
    20	            roomType.name()));
    21	
    22	        sb.append(String.format("Entrada: %s | Saída: %s | %d diária%s%n",
    23	            DateFormatter.format(reservation.getCheckIn()),
    24	            DateFormatter.format(reservation.getCheckOut()),
    25	            reservation.getNights(),
    26	            reservation.getNights() == 1 ? "" : "s"));
    27	
    28	        sb.append(String.format("Diárias: %s%n", MoneyFormatter.format(reservation.getSubtotal())));
    29	
    30	        if (reservation.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
    31	            sb.append(String.format("Desconto: %s%n", MoneyFormatter.format(reservation.getDiscount())));
    32	        }
    33	
